// Cycle number = how many cycles completed + 1
let pwCycleNum = Math.floor(cycleStartIndex / 36) + 1;

// Optional: track progress
let cycleProgress = filteredPW.length + "/" + 36; // e.g., "12/36 remaining until cycle complete"

  // 3. Frequency & Gaps
  let lsPwTotalHits = {};
